:"691190","slug":"ismael-mena"},{"mlb_id":"691251","slug":"andry-lara"},{"mlb_id":"691185","slug":"maximo-acosta"},{"mlb_id":"691252","slug":"jhon-diaz"},{"mlb_id":"691259","slug":"brayan-medina"},{"mlb_id":"691260","slug":"cristopher-cruz"},{"mlb_id":"691258","slug":"kristian-cardozo"},{"mlb_id":"691262","slug":"reginald-preciado"},{"mlb_id":"691263","slug":"esmerlin-vinicio"},{"mlb_id":"691265","slug":"junior-sanchez"},{"mlb_id":"691261","slug":"jose-pastrano"},{"mlb_id":"691267","slug":"alex-ramirez"},{"mlb_id":"691264","slug":"rikelbin-de-castro"},{"mlb_id":"691269","slug":"adrian-placencia"},{"mlb_id":"692294","slug":"luis-gutierrez"},{"mlb_id":"691266","slug":"brayan-altuve"}],"populations":["MLB-2019-PIPELINE-TOP30"],"publication_slug":"mlb-pipeline-top-30-international-signings"}$r056$::jsonb as j;

create temporary table _r056_dodgers_before on commit drop as
select md5(string_agg(t, '|' order by t)) as h from (select s::text as t from public.signings s join public.organizations o on o.id = s.organization_id where o.franchise_key = 'DODGERS') x;

-- ===========================================================================
-- 1. GUARDS
-- ===========================================================================

do $$
declare
  n int;
begin
  if (select count(*) from public.signing_populations where population_key in (select jsonb_array_elements_text(j -> 'populations') from _r056)) = 0 then
    raise exception 'rollback-056: Migration 056 is not applied';
  end if;
  -- later research must not depend on what is removed
  select count(*) into n from public.players pl
    where pl.slug in (select x ->> 'slug' from _r056, jsonb_array_elements(j -> 'new_players') x)
      and (exists (select 1 from public.player_season_stints s where s.player_id = pl.id)
        or exists (select 1 from public.development_milestones m where m.player_id = pl.id)
        or exists (select 1 from public.player_mlb_team_season_war w where w.player_id = pl.id or w.bref_id = pl.bref_id)
        or exists (select 1 from public.transaction_event_assets a where a.player_id = pl.id or a.mlb_id = pl.mlb_id::text)
        or exists (select 1 from public.player_career_transactions c where c.player_id = pl.id)
        or exists (select 1 from public.player_network_relationships r where r.player_id = pl.id)
        or (select count(*) from public.signings s where s.player_id = pl.id) <> 1
        or (select count(*) from public.player_evaluations e where e.player_id = pl.id) <> 1);
  if n > 0 then
    raise exception 'rollback-056: later research depends on % of the 056 benchmark players; rollback refused', n;
  end if;
end $$;

-- ===========================================================================
-- 2. THE 056 RANKINGS (the one sanctioned removal of sealed rows)
-- ===========================================================================

create temporary table _r056_eval on commit drop as
select e.id from public.player_evaluations e
join public.scouting_publications pub on pub.id = e.publication_id and pub.publication_slug = (select j ->> 'publication_slug' from _r056)
join public.players pl on pl.id = e.player_id
where pl.slug in (select x ->> 'slug' from _r056, jsonb_array_elements(j -> 'new_players') x);

alter table public.player_evaluations disable trigger player_evaluations_guard;
alter table public.player_evaluation_rankings disable trigger player_evaluation_rankings_immutable;
delete from public.player_evaluation_rankings where evaluation_id in (select id from _r056_eval);
delete from public.player_evaluations where id in (select id from _r056_eval);
alter table public.player_evaluation_rankings enable trigger player_evaluation_rankings_immutable;
alter table public.player_evaluations enable trigger player_evaluations_guard;

-- ===========================================================================
-- 3. THE BENCHMARK PLAYERS, SIGNINGS, MEMBERS, AUDITS, OUTCOMES AND EVIDENCE
-- ===========================================================================

create temporary table _r056_players on commit drop as
select pl.id, pl.slug from public.players pl where pl.slug in (select x ->> 'slug' from _r056, jsonb_array_elements(j -> 'new_players') x);

delete from public.evidence where entity_type = 'signing' and entity_id in (select s.id from public.signings s where s.player_id in (select id from _r056_players));
delete from public.evidence where entity_type = 'player' and entity_id in (select id from _r056_players);
delete from public.signing_population_member_sources where member_id in (select m.id from public.signing_population_members m
  join public.signings s on s.id = m.signing_id where s.player_id in (select id from _r056_players));
delete from public.signing_population_members where signing_id in (select s.id from public.signings s where s.player_id in (select id from _r056_players));
delete from public.outcomes where player_id in (select id from _r056_players);
delete from public.outcome_audits where player_id in (select id from _r056_players);
delete from public.outcome_evidence where player_id in (select id from _r056_players);
delete from public.player_aliases where player_id in (select id from _r056_players);
delete from public.signings where player_id in (select id from _r056_players);
delete from public.players where id in (select id from _r056_players);

-- ===========================================================================
-- 4. POPULATIONS AND THE STORED EVALUATION
-- ===========================================================================

create temporary table _r056_cov on commit drop as
select sp.legacy_coverage_id as id from public.signing_populations sp
where sp.population_key in (select jsonb_array_elements_text(j -> 'populations') from _r056) and sp.legacy_coverage_id is not null;
delete from public.signing_populations where population_key in (select jsonb_array_elements_text(j -> 'populations') from _r056);
delete from public.signing_census_coverage where id in (select id from _r056_cov);

update public.outcome_model_evaluations m set
  model_version = x ->> 'model_version', validation_method = x ->> 'validation_method',
  feature_list = array(select jsonb_array_elements_text(x -> 'feature_list')), training_populations = array(select jsonb_array_elements_text(x -> 'training_populations')),
  evaluated_rows = (x ->> 'evaluated_rows')::int, positive_n = (x ->> 'positive_n')::int, folds = (x ->> 'folds')::int,
  brier_score = (x ->> 'brier_score')::numeric, log_loss = (x ->> 'log_loss')::numeric, auc = (x ->> 'auc')::numeric,
  brier_skill_vs_base_rate = (x ->> 'brier_skill_vs_base_rate')::numeric, calibration_bins = x -> 'calibration_bins', decision = x ->> 'decision',
  decision_reason = x ->> 'decision_reason', training_fingerprint = x ->> 'training_fingerprint', data_as_of_date = (x ->> 'data_as_of_date')::date
from _r056, jsonb_array_elements(j -> 'evaluation_055') x
where m.target_key = x ->> 'target_key' and m.model_key = x ->> 'model_key';

-- ===========================================================================
-- 5. POSTCONDITIONS AND ONE REFRESH
-- ===========================================================================

do $$
begin
  if (select count(*) from public.players) <> (select (j #>> '{baseline,counts,players}')::int from _r056)
     or (select count(*) from public.signings where record_scope = 'MLB_PIPELINE_TOP_PROSPECT') <> (select (j #>> '{baseline,counts,benchmark_signings}')::int from _r056)
     or (select count(*) from public.outcome_audits) <> (select (j #>> '{baseline,counts,outcome_audits}')::int from _r056)
     or (select count(*) from public.outcomes) <> (select (j #>> '{baseline,counts,outcomes}')::int from _r056)
     or (select count(*) from public.player_evaluations) <> (select (j #>> '{baseline,counts,player_evaluations}')::int from _r056)
     or (select count(*) from public.signing_populations) <> (select (j #>> '{baseline,counts,signing_populations}')::int from _r056)
     or (select count(*) from public.signing_population_members) <> (select (j #>> '{baseline,counts,population_members}')::int from _r056)
     or (select count(*) from public.signing_census_coverage) <> (select (j #>> '{baseline,counts,census_coverage_rows}')::int from _r056) then
    raise exception 'rollback-056 postcondition: the pre-056 counts are not restored';
  end if;
  if exists (select 1 from public.outcome_model_evaluations where training_fingerprint <> (select j #>> '{baseline,evaluation,0,training_fingerprint}' from _r056)) then
    raise exception 'rollback-056 postcondition: the stored 055 evaluation is not restored';
  end if;
  if (select h from _r056_dodgers_before) is distinct from (select md5(string_agg(t, '|' order by t)) from (select s::text as t from public.signings s join public.organizations o on o.id = s.organization_id where o.franchise_key = 'DODGERS') x)
     or (select count(*) from _r056, jsonb_array_elements(j -> 'dodgers_mapped') x
         where (select count(*) from public.signings s join public.players pl on pl.id = s.player_id
                where pl.slug = x ->> 'slug' and s.international_rank is not distinct from (x ->> 'stored_international_rank')::numeric) <> 1) > 0 then
    raise exception 'rollback-056 postcondition: a Dodgers signing changed';
  end if;
  if exists (select 1 from pg_trigger t join pg_class c on c.oid = t.tgrelid where c.relname in ('player_evaluations', 'player_evaluation_rankings')
             and not t.tgisinternal and t.tgenabled <> 'O') then
    raise exception 'rollback-056 postcondition: an evaluation guard trigger is not enabled';
  end if;
end $$;

select * from public.disi_refresh_product_snapshots();

commit;
